const cats=['Regional Amateur','Primera División','Tercera División','Quinta División','Sexta División','Séptima División','Octava División','Preoctava','División Senior'];
const catColors=['#99621b','#168244','#2357b5','#007eac','#2c65b6','#8337b5','#5937a2','#303846','#c51f53'];
const catCodes=['RA','1ª','3ª','5ª','6ª','7ª','8ª','PRE','SR'];
const teams=['Atlético del Norte','Unión del Sur','Deportivo Central','Juventud Unida','Sportivo del Este','Independiente','San Martín','Belgrano'];
const colors=['#397e48','#b53b42','#254c94','#df9e28','#1f6f9b','#b52c38','#398278','#343b51'];
const fixtures=[[[0,1,'2 – 1','live'],[2,3,'0 – 0','live'],[4,5,'3 – 1','final'],[6,7,'–','17:00']],[[3,4,'1 – 0','final'],[5,0,'2 – 2','final'],[7,2,'–','17:30']],[[1,6,'0 – 1','final'],[0,4,'–','18:00']],[[2,6,'2 – 0','final'],[4,7,'1 – 1','final'],[1,3,'–','18:30']]];
let selected=null,filter='all',offset=0,tabState={},season='Clausura 2026';
const $=s=>document.querySelector(s);
function badge(i){return `<span class="shield" style="--club:${colors[i]}">${teams[i].split(' ').map(w=>w[0]).join('')}</span>`}
function table(g=false){return `<table class="fulltable"><thead><tr><th>#</th><th>${g?'Jugador':'Equipo'}</th><th>${g?'Club':'PJ'}</th><th>${g?'Goles':'PTS'}</th></tr></thead><tbody>${teams.map((t,i)=>`<tr><td>${i+1}</td><td>${g?['M. González','J. Rodríguez','L. Martínez','F. López','N. Pérez','S. García','T. Fernández','A. Gómez'][i]:t}</td><td>${g?t:8}</td><td><b>${g?12-i:20-i*2}</b></td></tr>`).join('')}</tbody></table>`}
function render(){let d=new Date(2026,10,11+offset);$('#date').textContent=(offset===0?'HOY · ':'')+d.toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();$('#pagetitle').textContent=selected===null?'Hoy se juega.':cats[selected];document.querySelectorAll('.catbtn').forEach((b,i)=>b.classList.toggle('active',selected===i));$('#all').classList.toggle('active',selected===null);document.querySelectorAll('.categorychip').forEach(b=>b.classList.toggle('active',+b.dataset.category===selected));const baseIndexes=selected===null?[1,2,3,4,5,6,7,8,0]:[selected];const allMatches=baseIndexes.flatMap((ci,idx)=>selected===null?fixtures[idx%4]:fixtures[ci%4]);document.querySelector('[data-filter=all] .count').textContent=allMatches.length;document.querySelector('[data-filter=live] .count').textContent=offset===0?allMatches.filter(m=>m[3]==='live').length:0;let indexes=selected===null?[1,2,3,4,5,6,7,8,0]:[selected];$('#competitions').innerHTML=indexes.map((ci,idx)=>{let matches=selected===null?fixtures[idx%4]:fixtures[ci%4];if(offset!==0)matches=matches.map(m=>[m[0],m[1],'–','17:00']);let shown=matches.filter(m=>filter==='all'||m[3]===filter);let tab=tabState[ci]||'Partidos';return `<section class="competition" style="--category:${catColors[ci]}"><div class="comphead"><div class="comptitle"><span class="symbol">${catCodes[ci]}</span><div><h2>${cats[ci].toUpperCase()}</h2><small>${season}${ci===0?' · Litoral Sur':' · Fecha 8'}</small></div></div><span style="font-size:10px;color:#c8d2e6">${matches.length} partidos</span></div><div class="tabs">${['Partidos','Posiciones','Goleadores'].map(t=>`<button class="tab ${tab===t?'active':''}" data-cat="${ci}" data-tab="${t}">${t}</button>`).join('')}</div>${tab==='Partidos'?(shown.length?shown.map((m,i)=>`<div class="match"><span class="status ${m[3]==='live'?'live':''}">${m[3]==='live'?'<span class="dot"></span>'+["64′","32′"][i%2]:m[3]==='final'?'Final':m[3]}</span><div class="team home"><span>${teams[m[0]]}</span>${badge(m[0])}</div><span class="score ${m[3]==='live'?'live':''}">${m[2]}</span><div class="team">${badge(m[1])}<span>${teams[m[1]]}</span></div></div>`).join(''):'<div class="empty">No hay partidos con este filtro.</div>'):table(tab==='Goleadores')}<div class="compfoot">${tab==='Partidos'?'Resultados de ejemplo':'Clasificación ilustrativa'} <span style="padding:0 8px">·</span> <b>${cats[ci]}</b></div></section>`}).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tabState[b.dataset.cat]=b.dataset.tab;render()});}
$('#categoryrail').innerHTML=cats.map((c,i)=>`<button class="categorychip" style="--category:${catColors[i]}" data-category="${i}">${c}</button>`).join('');document.querySelectorAll('.categorychip').forEach(b=>b.onclick=()=>{selected=+b.dataset.category;render()});
$('#categories').innerHTML=cats.map((c,i)=>`<button class="catbtn" style="--category:${catColors[i]}" data-i="${i}">${c}<span>›</span></button>`).join('');document.querySelectorAll('.catbtn').forEach(b=>b.onclick=()=>{selected=+b.dataset.i;$('.sidebar').classList.remove('open');render()});$('#all').onclick=()=>{selected=null;$('.sidebar').classList.remove('open');render()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#prev').onclick=()=>{offset--;render()};$('#next').onclick=()=>{offset++;render()};$('.season').onchange=e=>{season=e.target.value;render()};$('#minitable').innerHTML=teams.slice(0,5).map((t,i)=>`<tr><td>${i+1}</td><td>${t}</td><td>8</td><td>${20-i*2}</td></tr>`).join('');$('#fullstandings').onclick=()=>{selected=1;tabState[1]='Posiciones';render();window.scrollTo({top:0,behavior:'smooth'})};$('#newsnav').onclick=()=>{$('.sidebar').classList.remove('open');$('#news').scrollIntoView({behavior:'smooth',block:'center'})};$('.menu').onclick=()=>$('.sidebar').classList.toggle('open');document.addEventListener('click',e=>{if(!e.target.closest('.sidebar')&&!e.target.closest('.menu'))$('.sidebar').classList.remove('open')});render();
